// ═══ allOf: returns Void — must join individually ═══
CF<Integer> balanceCF = supplyAsync(() -> getBalance("SAV2001"));
CF<Integer> scoreCF = supplyAsync(() -> getCreditScore("SAV2001"));
CF<BigDecimal> propertyCF = supplyAsync(() -> getPropertyValue("P001"));

CompletableFuture<Void> allDone = CompletableFuture.allOf(balanceCF, scoreCF, propertyCF);
allDone.join();  // waits for ALL three. Returns null (Void)!

// Must join EACH to get results:
int balance = balanceCF.join();
int score = scoreCF.join();
BigDecimal property = propertyCF.join();

// ═══ STRATEGY 1: FAIL-ALL ═══
// If ANY future threw → allOf().join() throws CompletionException
// Entire operation fails. Strict consistency.
try {
    CompletableFuture.allOf(balanceCF, scoreCF, propertyCF).join();
    // All succeeded → collect results
} catch (CompletionException e) {
    // At least one failed → reject entire loan application
    return "REJECTED: " + e.getCause().getMessage();
}

// ═══ STRATEGY 2: PARTIAL RESULTS ═══
CompletableFuture.allOf(balanceCF, scoreCF, propertyCF)
    .exceptionally(ex -> null)  // swallow allOf exception
    .join();

Map<String, Object> results = new HashMap<>();
if (!balanceCF.isCompletedExceptionally()) results.put("balance", balanceCF.join());
if (!scoreCF.isCompletedExceptionally()) results.put("score", scoreCF.join());
if (!propertyCF.isCompletedExceptionally()) results.put("property", propertyCF.join());
// Return whatever succeeded!

// ═══ STRATEGY 3: FALLBACKS (best for resilience!) ═══
CF<Integer> safeBalance = balanceCF.exceptionally(ex -> 0);         // fallback: 0
CF<Integer> safeScore = scoreCF.exceptionally(ex -> 500);           // fallback: 500
CF<BigDecimal> safeProperty = propertyCF.exceptionally(ex -> BigDecimal.ZERO);

CompletableFuture.allOf(safeBalance, safeScore, safeProperty).join();
// ALL always succeed (with real or fallback values!)
int b = safeBalance.join();   // real value or 0
int s = safeScore.join();     // real value or 500
