// ─── File: src/test/java/com/bank/allof/AllOfStrategiesTest.java ───
package com.bank.allof;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class AllOfStrategiesTest {

    // ═══ allOf returns Void — join each individually ═══
    @Test
    void allOf_returnsVoid_joinIndividually() throws Exception {
        CompletableFuture<Integer> cf1 = CompletableFuture.supplyAsync(() -> 100000);
        CompletableFuture<String> cf2 = CompletableFuture.supplyAsync(() -> "Rajesh");

        Void result = CompletableFuture.allOf(cf1, cf2).get();
        assertThat(result).isNull();  // Void!

        assertThat(cf1.join()).isEqualTo(100000);
        assertThat(cf2.join()).isEqualTo("Rajesh");
    }

    // ═══ STRATEGY 1: fail-all ═══
    @Test
    void failAll_oneFailureRejectsAll() {
        CompletableFuture<Integer> good = CompletableFuture.supplyAsync(() -> 100000);
        CompletableFuture<Integer> bad = CompletableFuture.supplyAsync(() -> {
            throw new RuntimeException("Credit bureau down!");
        });

        assertThatThrownBy(() -> CompletableFuture.allOf(good, bad).join())
            .isInstanceOf(CompletionException.class);
    }

    // ═══ STRATEGY 2: partial results ═══
    @Test
    void partialResults_collectWhatSucceeded() {
        CompletableFuture<Integer> balance = CompletableFuture.supplyAsync(() -> 100000);
        CompletableFuture<Integer> score = CompletableFuture.supplyAsync(() -> {
            throw new RuntimeException("Timeout!");
        });
        CompletableFuture<Integer> property = CompletableFuture.supplyAsync(() -> 5000000);

        CompletableFuture.allOf(balance, score, property).exceptionally(ex -> null).join();

        Map<String, Integer> results = new HashMap<>();
        if (!balance.isCompletedExceptionally()) results.put("balance", balance.join());
        if (!score.isCompletedExceptionally()) results.put("score", -1);  // missing!
        if (!property.isCompletedExceptionally()) results.put("property", property.join());

        assertThat(results).containsKeys("balance", "property");
        assertThat(results).hasSize(3);  // 2 real + 1 placeholder
    }

    // ═══ STRATEGY 3: fallbacks (most resilient) ═══
    @Test
    void fallbacks_allAlwaysSucceed() {
        CompletableFuture<Integer> balance = CompletableFuture.supplyAsync(() -> 100000);
        CompletableFuture<Integer> score = CompletableFuture
            .<Integer>supplyAsync(() -> { throw new RuntimeException("Down!"); })
            .exceptionally(ex -> 500);  // fallback!
        CompletableFuture<Integer> property = CompletableFuture.supplyAsync(() -> 5000000);

        CompletableFuture.allOf(balance, score, property).join();  // no exception!

        assertThat(balance.join()).isEqualTo(100000);
        assertThat(score.join()).isEqualTo(500);  // fallback value!
        assertThat(property.join()).isEqualTo(5000000);
    }

    // ═══ Collecting results into a list ═══
    @Test
    void collectResults_intoList() {
        List<CompletableFuture<String>> futures = List.of(
            CompletableFuture.supplyAsync(() -> "TRD-001"),
            CompletableFuture.supplyAsync(() -> "TRD-002"),
            CompletableFuture.supplyAsync(() -> "TRD-003")
        );

        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();

        List<String> results = futures.stream()
            .map(CompletableFuture::join)
            .toList();

        assertThat(results).containsExactly("TRD-001", "TRD-002", "TRD-003");
    }
}
